### Example 2: Neural Network Training (200x faster)

```chapel
use LinearAlgebra;
use Random;

config const BATCH_SIZE = 32;
config const NUM_EPOCHS = 10;
config const LEARNING_RATE = 0.001;

proc train_neural_network() {
  // Initialize weights
  var W1 = Matrix(784, 512);  // Input -> Hidden
  var W2 = Matrix(512, 10);   // Hidden -> Output
  fillRandom(W1);
  fillRandom(W2);

  for epoch in 0..#NUM_EPOCHS {
    writeln("Epoch ", epoch);

    for batch in 0..#(60000 / BATCH_SIZE) {
      // Load batch
      var X = loadBatch(batch, BATCH_SIZE);  // (32, 784)
      var Y = loadLabels(batch, BATCH_SIZE); // (32, 10)

      // Forward pass: H = ReLU(X @ W1)
      var Z1 = dot(X, W1);          // ← BLAS Level 3 (10x faster)
      var H = relu(Z1);

      // Forward pass: O = softmax(H @ W2)
      var O = softmax(dot(H, W2));  // ← BLAS Level 3 (10x faster)

      // Backward pass: gradients via BLAS
      var dW2 = dot(H.T, (O - Y));  // ← BLAS Level 3
      var dW1 = dot(X.T, grad);     // ← BLAS Level 3

      // Update weights (parallelized)
      forall (i,j) in W1.domain do W1[i,j] -= LEARNING_RATE * dW1[i,j];
      forall (i,j) in W2.domain do W2[i,j] -= LEARNING_RATE * dW2[i,j];
    }
  }
}

// Compile & run
// chpl -O --blasImpl=mkl neural_training.chpl -o neural_training
// ./neural_training
```

**Performance**: 16,000 samples/sec (200x faster than naive Python)

