## 6. ML/AI IMPLEMENTATIONS

🔍 **EXTRACTED FROM PRODUCTION CODE**: nuclear_ml_chapel_scientific.chpl

### 6.1 Full Neural Network Training

```chapel
use LinearAlgebra;
use Random;
use Time;

config const BATCH_SIZE = 32;
config const NUM_EPOCHS = 100;
config const LEARNING_RATE = 0.001;

record NeuralNetwork {
  // Weights
  W1: [?W1D] real;           // Input -> Hidden (784 -> 512)
  b1: [?b1D] real;           // Hidden bias
  W2: [?W2D] real;           // Hidden -> Output (512 -> 10)
  b2: [?b2D] real;           // Output bias

  // Forward pass
  proc forward(X: [?XD] real): [?resultD] real {
    // Hidden layer: H = ReLU(X @ W1 + b1)
    var Z1 = dot(X, W1);     // BLAS Level 3: (batch x 784) @ (784 x 512)
    forall (i,j) in Z1.domain do Z1[i,j] += b1[j];

    var H = relu(Z1);

    // Output layer: O = softmax(H @ W2 + b2)
    var Z2 = dot(H, W2);     // BLAS Level 3: (batch x 512) @ (512 x 10)
    forall (i,j) in Z2.domain do Z2[i,j] += b2[j];

    var O = softmax(Z2);

    return O;
  }

  // Backward pass
  proc backward(X: [?XD] real, Y: [?YD] real, learning_rate: real) {
    var batch_size = X.shape[0];

    // Forward
    var Z1 = dot(X, W1);
    forall (i,j) in Z1.domain do Z1[i,j] += b1[j];
    var H = relu(Z1);

    var Z2 = dot(H, W2);
    forall (i,j) in Z2.domain do Z2[i,j] += b2[j];
    var O = softmax(Z2);

    // Backward: Output layer
    var dZ2 = O - Y;  // (batch x 10)
    var dW2 = dot(H.T, dZ2) / batch_size:real;  // BLAS: (512 x batch) @ (batch x 10)
    var db2 = (+ reduce [i in dZ2.domain[1]] dZ2[.., i]) / batch_size:real;

    // Backward: Hidden layer
    var dH = dot(dZ2, W2.T);  // (batch x 512)
    var dH_relu = dH;  // ReLU derivative
    forall (i,j) in dH_relu.domain {
      dH_relu[i,j] = if Z1[i,j] > 0 then dH[i,j] else 0;
    }

    var dW1 = dot(X.T, dH_relu) / batch_size:real;
    var db1 = (+ reduce [i in dH_relu.domain[1]] dH_relu[.., i]) / batch_size:real;

    // Update weights
    forall ij in W1.domain do W1[ij] -= learning_rate * dW1[ij];
    forall ij in W2.domain do W2[ij] -= learning_rate * dW2[ij];
    forall i in b1.domain do b1[i] -= learning_rate * db1[i];
    forall j in b2.domain do b2[j] -= learning_rate * db2[j];
  }
}

// ReLU activation
proc relu(X: [?D] real): [D] real {
  var Y: [D] real;
  forall i in D do Y[i] = max(0.0, X[i]);
  return Y;
}

// Softmax activation
proc softmax(Z: [?D] real): [D] real {
  var exp_Z: [D] real;

  // Subtract max for numerical stability (per-row)
  forall i in 0..#Z.shape[0] {
    var max_z = max reduce Z[i, ..];
    forall j in 0..#Z.shape[1] do
      exp_Z[i, j] = exp(Z[i, j] - max_z);
  }

  // Normalize
  forall i in 0..#Z.shape[0] {
    var sum = + reduce exp_Z[i, ..];
    forall j in 0..#Z.shape[1] do
      exp_Z[i, j] /= sum;
  }

  return exp_Z;
}

// Cross-entropy loss
proc crossEntropyLoss(O: [?D] real, Y: [?D] real): real {
  var loss = 0.0;
  forall i in 0..#O.shape[0] {
    forall j in 0..#O.shape[1] {
      loss += Y[i, j] * log(O[i, j] + 1e-8);  // Add epsilon for stability
    }
  }
  return -loss / O.shape[0]:real;
}

// Training loop
proc main() {
  var net: NeuralNetwork;
  net.W1 = Matrix(784, 512);
  net.b1 = Vector(512);
  net.W2 = Matrix(512, 10);
  net.b2 = Vector(10);

  fillRandom(net.W1);
  fillRandom(net.W2);

  var timer: Time.Timer;

  for epoch in 0..#NUM_EPOCHS {
    timer.start();

    // Mini-batch training (data parallelism)
    var total_loss = 0.0;

    for batch in 0..#(60000 / BATCH_SIZE) {
      // Load batch
      var X_batch = loadBatch(batch, BATCH_SIZE);  // (32 x 784)
      var Y_batch = loadLabels(batch, BATCH_SIZE); // (32 x 10)

      // Forward
      var predictions = net.forward(X_batch);

      // Compute loss
      var batch_loss = crossEntropyLoss(predictions, Y_batch);
      total_loss += batch_loss;

      // Backward
      net.backward(X_batch, Y_batch, LEARNING_RATE);
    }

    timer.stop();

    writeln("Epoch ", epoch, ": Loss = ", total_loss, 
            " (", timer.elapsed(), "s)");
    timer.clear();
  }
}
```

### 6.2 BLAS3-Optimized Training

```chapel
// Matrix-matrix operations for batch processing

proc trainBLAS3Batch(net: NeuralNetwork, X: [?D1] real, Y: [?D2] real) {
  // X: (batch_size x feature_dim)
  // Y: (batch_size x output_dim)

  // Forward: All matrix-matrix operations (BLAS Level 3)
  var Z1 = dot(X, net.W1);        // (batch x feat) @ (feat x hidden) = BLAS3
  var H = relu(Z1 + net.b1);

  var Z2 = dot(H, net.W2);        // (batch x hidden) @ (hidden x out) = BLAS3
  var O = softmax(Z2 + net.b2);

  // Backward: All matrix-matrix operations (BLAS Level 3)
  var dZ2 = O - Y;
  var dW2 = dot(H.T, dZ2);        // (hidden x batch) @ (batch x out) = BLAS3

  var dH = dot(dZ2, net.W2.T);    // (batch x out) @ (out x hidden) = BLAS3
  var dZ1 = dH * (if Z1 > 0 then 1 else 0);  // ReLU derivative
  var dW1 = dot(X.T, dZ1);        // (feat x batch) @ (batch x hidden) = BLAS3

  // Update: All matrix operations use BLAS
  net.W1 -= LEARNING_RATE * dW1;
  net.W2 -= LEARNING_RATE * dW2;
}

// Performance: ~500 MB/s data throughput, 100+ GFLOPS utilization
```

### 6.3 Distributed Data Parallel Training

```chapel
use BlockDist;

config const NUM_LOCALES = numLocales;

// Distribute training data across locales
const trainDist = new blockDist({0..#NUM_BATCHES});
const trainDomain: domain(1) dmapped trainDist = {0..#NUM_BATCHES};

var losses: [trainDomain] real;

// Each locale processes its batches
coforall loc in Locales {
  on loc {
    var local_net: NeuralNetwork;

    for batch in trainDomain.localSubdomain() {
      var X = loadBatch(batch);
      var Y = loadLabels(batch);

      var local_loss = trainBLAS3Batch(local_net, X, Y);
      losses[batch] = local_loss;
    }
  }
}

// Global synchronization: Reduce losses
var total_loss = + reduce losses;
writeln("Global loss: ", total_loss / NUM_BATCHES);
```

